-- 3
SELECT SUM(YEARMONTH.CONSUMPTION) / 12 FROM CUSTOMERS INNER JOIN YEARMONTH ON CUSTOMERS.CUSTOMERID = YEARMONTH.CUSTOMERID WHERE CUSTOMERS.CURRENCY = 'EUR';
-- ----------sql2------------
-- 2
